def protocol_prefix_hash(path):
    raw = path.read_bytes()
    at = raw.index(b"`protocol_sha256=")
    return hashlib.sha256(raw[:at]).hexdigest().upper()


def manual_point_count(p):
    # #E(F_p)=1+sum_x(1+Legendre(x^3-x,p)); the leading 1 is infinity.
    return _sage_const_1  + sum(_sage_const_1  + kronecker_symbol((x**_sage_const_3  - x) % p, p) for x in range(p))


def primary_gaussian_trace(p):
    """Trace pi+conjugate(pi) for the conductor-32 primary convention.

    For p=1 mod 4 choose pi=u+i*v with u odd, v even, and u+v=1 mod 4.
    Conjugation may leave two values of v, but the real part and trace are
    unique.  No quadrant is selected from a target trace.
    """
    bound = floor(sqrt(p))
    traces = set()
    for u in range(-bound, bound + _sage_const_1 ):
        for v in range(-bound, bound + _sage_const_1 ):
            if u*u + v*v != p:
                continue
            if u % _sage_const_2  == _sage_const_0  or v % _sage_const_2  != _sage_const_0 :
                continue
            if (u + v - _sage_const_1 ) % _sage_const_4  == _sage_const_0 :
                traces.add(_sage_const_2 *u)
    if len(traces) != _sage_const_1 :
        raise AssertionError(f"primary trace not unique at p={p}: {traces}")
    return traces.pop()


def hecke_coefficients(E, limit):
    """Generate a_n from fixed local Euler factors, including bad p=2."""
    coeff = [ZZ(_sage_const_0 )] * limit
    coeff[_sage_const_1 ] = ZZ(_sage_const_1 )
    for n in range(_sage_const_2 , limit):
        fac = factor(n)
        value = ZZ(_sage_const_1 )
        for p, exponent in fac:
            p = ZZ(p)
            if p == _sage_const_2 :
                # Additive reduction: local factor is 1, so a_(2^r)=0.
                value = ZZ(_sage_const_0 )
                break
            a0 = ZZ(_sage_const_1 )
            a1 = ZZ(E.ap(p))
            if exponent == _sage_const_1 :
                power_coeff = a1
            else:
                prev2, prev1 = a0, a1
                for _ in range(_sage_const_2 , exponent + _sage_const_1 ):
                    current = E.ap(p) * prev1 - p * prev2
                    prev2, prev1 = prev1, current
                power_coeff = prev1
            value *= power_coeff
        coeff[n] = value
    return coeff


def eta_product_coefficients(limit):
    """q-product eta(4 tau)^2 eta(8 tau)^2 through q^(limit-1)."""
    PS = PowerSeriesRing(QQ, "q", default_prec=limit)
    q = PS.gen()
    product = q
    for n in range(_sage_const_1 , (limit - _sage_const_1 )//_sage_const_4  + _sage_const_1 ):
        product *= (_sage_const_1  - q**(_sage_const_4 *n))**_sage_const_2 
    for n in range(_sage_const_1 , (limit - _sage_const_1 )//_sage_const_8  + _sage_const_1 ):
        product *= (_sage_const_1  - q**(_sage_const_8 *n))**_sage_const_2 
    return [ZZ(product[n]) for n in range(limit)]


def sym2_polynomial(trace, determinant, X):
    return (
        X**_sage_const_3 
        - (trace**_sage_const_2  - determinant) * X**_sage_const_2 
        + determinant * (trace**_sage_const_2  - determinant) * X
        - determinant**_sage_const_3 
    )


