    varpi = gamma14**_sage_const_2  / (_sage_const_2  * sqrt(_sage_const_2  * pi_rf))
    gstar = _sage_const_2  * varpi / sqrt(pi_rf)
    sage_period = RF(E.period_lattice().real_period())
