    cert.check("BSD invariant quotient is varpi/4", abs(bsd_from_invariants - varpi/_sage_const_4 ) < RF(_sage_const_2 )**-_sage_const_190 )
    L1 = RF(E.lseries().dokchitser(prec=_sage_const_200 )(_sage_const_1 ).real())
